-- ==============================================================================
-- PROJECT: vesse_app
-- SCHEMA CREATION SCRIPT (01-schema.sql)
-- Database: PostgreSQL (PostGIS Extension required for GEOGRAPHY type)
-- Primary Key Strategy: GENERATED BY DEFAULT AS IDENTITY
-- ==============================================================================

-- 1. Enable PostGIS Extension for GEOGRAPHY data type
CREATE EXTENSION IF NOT EXISTS postgis;

-- ------------------------------------------------------------------------------
-- DROP TABLES (If re-running schema)
-- ------------------------------------------------------------------------------
DROP TABLE IF EXISTS "Shipment" CASCADE;
DROP TABLE IF EXISTS "VesselMatch" CASCADE;
DROP TABLE IF EXISTS "BookingReview" CASCADE;
DROP TABLE IF EXISTS "RoutePort" CASCADE;
DROP TABLE IF EXISTS "Booking" CASCADE;
DROP TABLE IF EXISTS "Vessel" CASCADE;
DROP TABLE IF EXISTS "Port" CASCADE;
DROP TABLE IF EXISTS "Route" CASCADE;
DROP TABLE IF EXISTS "User" CASCADE;
DROP TABLE IF EXISTS "Role" CASCADE;

-- ------------------------------------------------------------------------------
-- 1. TABLE: Role
-- ------------------------------------------------------------------------------
CREATE TABLE "Role" (
  "role_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "role_name" VARCHAR(100),
  "role_code" VARCHAR(50) UNIQUE NOT NULL
);

-- ------------------------------------------------------------------------------
-- 2. TABLE: User
-- ------------------------------------------------------------------------------
CREATE TABLE "User" (
  "user_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_name" VARCHAR(100) NOT NULL,
  "user_pwd" VARCHAR(255) NOT NULL,
  "user_phone" VARCHAR(20),
  "user_email" VARCHAR(150),
  "user_status" VARCHAR(50) DEFAULT 'ACTIVE',
  "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" TIMESTAMP,
  "role_id" INT NOT NULL,
  CONSTRAINT "fk_user_role" FOREIGN KEY ("role_id") REFERENCES "Role" ("role_id") ON DELETE RESTRICT,
  CONSTRAINT "chk_user_status" CHECK ("user_status" IN ('ACTIVE', 'INACTIVE', 'LOCKED'))
);

-- ------------------------------------------------------------------------------
-- 3. TABLE: Port
-- ------------------------------------------------------------------------------
CREATE TABLE "Port" (
  "port_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "port_name" VARCHAR(150) NOT NULL,
  "port_geo" GEOGRAPHY(Point, 4326),
  "user_id" INT UNIQUE,
  CONSTRAINT "fk_port_user" FOREIGN KEY ("user_id") REFERENCES "User" ("user_id") ON DELETE SET NULL
);

-- Spatial Index cho PostGIS (Tối ưu tìm kiếm tọa độ cảng)
CREATE INDEX "idx_port_geo" ON "Port" USING GIST ("port_geo");

-- ------------------------------------------------------------------------------
-- 4. TABLE: Vessel
-- ------------------------------------------------------------------------------
CREATE TABLE "Vessel" (
  "vessel_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "vessel_owner_name" VARCHAR(150),
  "vessel_status" VARCHAR(50) DEFAULT 'AVAILABLE',
  "vessel_capacity" DECIMAL(10, 2),
  "vessel_cargo_type" VARCHAR(100),
  "user_id" INT UNIQUE,
  CONSTRAINT "fk_vessel_user" FOREIGN KEY ("user_id") REFERENCES "User" ("user_id") ON DELETE SET NULL,
  CONSTRAINT "chk_vessel_status" CHECK ("vessel_status" IN ('AVAILABLE', 'IN_TRANSIT', 'MAINTENANCE', 'INACTIVE'))
);

-- ------------------------------------------------------------------------------
-- 5. TABLE: Route
-- ------------------------------------------------------------------------------
CREATE TABLE "Route" (
  "route_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "route_code" VARCHAR(100) UNIQUE NOT NULL,
  "updated_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" TIMESTAMP
);

-- ------------------------------------------------------------------------------
-- 6. TABLE: RoutePort
-- ------------------------------------------------------------------------------
CREATE TABLE "RoutePort" (
  "routeport_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "route_id" INT NOT NULL,
  "port_id" INT NOT NULL,
  CONSTRAINT "fk_routeport_route" FOREIGN KEY ("route_id") REFERENCES "Route" ("route_id") ON DELETE CASCADE,
  CONSTRAINT "fk_routeport_port" FOREIGN KEY ("port_id") REFERENCES "Port" ("port_id") ON DELETE CASCADE
);

CREATE UNIQUE INDEX "idx_routeport_route_port" ON "RoutePort" ("route_id", "port_id");

-- ------------------------------------------------------------------------------
-- 7. TABLE: Booking
-- ------------------------------------------------------------------------------
CREATE TABLE "Booking" (
  "booking_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "booking_date" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  "receive_date" TIMESTAMP,
  "expected_date" TIMESTAMP,
  "expired_date" TIMESTAMP,
  "booking_status" VARCHAR(50) DEFAULT 'PENDING',
  "cargo_type" VARCHAR(100),
  "cargo_capacity" DECIMAL(10, 2),
  "user_id" INT,
  "route_id" INT,
  CONSTRAINT "fk_booking_user" FOREIGN KEY ("user_id") REFERENCES "User" ("user_id") ON DELETE SET NULL,
  CONSTRAINT "fk_booking_route" FOREIGN KEY ("route_id") REFERENCES "Route" ("route_id") ON DELETE SET NULL,
  CONSTRAINT "chk_booking_status" CHECK ("booking_status" IN ('PENDING', 'APPROVED', 'MATCHED', 'IN_PROGRESS', 'COMPLETED', 'CANCELLED', 'EXPIRED'))
);

-- ------------------------------------------------------------------------------
-- 8. TABLE: BookingReview
-- ------------------------------------------------------------------------------
CREATE TABLE "BookingReview" (
  "review_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "booking_id" INT NOT NULL,
  "port_id" INT NOT NULL,
  "review_status" VARCHAR(50) DEFAULT 'PENDING',
  "review_date" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "fk_review_booking" FOREIGN KEY ("booking_id") REFERENCES "Booking" ("booking_id") ON DELETE CASCADE,
  CONSTRAINT "fk_review_port" FOREIGN KEY ("port_id") REFERENCES "Port" ("port_id") ON DELETE RESTRICT,
  CONSTRAINT "chk_review_status" CHECK ("review_status" IN ('PENDING', 'APPROVED', 'REJECTED', 'REQUIRES_UPDATE'))
);

CREATE UNIQUE INDEX "idx_bookingreview_booking_port" ON "BookingReview" ("booking_id", "port_id");

-- ------------------------------------------------------------------------------
-- 9. TABLE: VesselMatch
-- ------------------------------------------------------------------------------
CREATE TABLE "VesselMatch" (
  "match_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "vessel_id" INT NOT NULL,
  "booking_id" INT NOT NULL,
  CONSTRAINT "fk_match_vessel" FOREIGN KEY ("vessel_id") REFERENCES "Vessel" ("vessel_id") ON DELETE CASCADE,
  CONSTRAINT "fk_match_booking" FOREIGN KEY ("booking_id") REFERENCES "Booking" ("booking_id") ON DELETE CASCADE
);

-- ------------------------------------------------------------------------------
-- 10. TABLE: Shipment
-- ------------------------------------------------------------------------------
CREATE TABLE "Shipment" (
  "shipment_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "shipment_status" VARCHAR(50) DEFAULT 'PLANNED',
  "shipment_date" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  "vessel_id" INT,
  "review_id" INT,
  CONSTRAINT "fk_shipment_vessel" FOREIGN KEY ("vessel_id") REFERENCES "Vessel" ("vessel_id") ON DELETE SET NULL,
  CONSTRAINT "fk_shipment_review" FOREIGN KEY ("review_id") REFERENCES "BookingReview" ("review_id") ON DELETE SET NULL,
  CONSTRAINT "chk_shipment_status" CHECK ("shipment_status" IN ('PLANNED', 'LOADING', 'IN_TRANSIT', 'DELIVERED', 'CANCELLED'))
);